SELECT * FROM job_match_record 
WHERE job_id = #{jobId} 
ORDER BY match_score DESC

SELECT * FROM job_match_record 
WHERE student_id = #{studentId} 
ORDER BY create_time DESC

SELECT * FROM job_match_record 
WHERE match_score BETWEEN #{minScore} AND #{maxScore}
ORDER BY match_score DESC

mapper.update:
UPDATE job_match_record 
SET is_pushed = 1, push_time = #{pushTime}
WHERE id = #{id}

UPDATE job_match_record 
SET is_clicked = 1, click_time = NOW()
WHERE id = #{id}
